export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type Category = "standard" | "suite" | "villa";
type Season = "low" | "high";

interface RawBooking {
  category: Category;
  loyaltyYears: number;
  coupon?: unknown;
  nights: unknown;
  guests: unknown;
  season: unknown;
}

/**
 * Per-category pricing and validation rules.
 */
interface CategoryRules {
  maxNights: number;
  maxGuests: number;
  rate: number; // per-night base rate
  peakRate: number; // extra per night during high season
  minStay?: number; // optional minimum stay (villa); produces a dedicated error
  guestSurcharge?: number; // flat fee when guests exceed the threshold (suite)
  guestSurchargeThreshold?: number;
  fixedFee?: number; // flat fee always added (villa)
}

const CATEGORIES: Record<Category, CategoryRules> = {
  standard

: { maxNights: 14, maxGuests: 2, rate: 80, peakRate: 30 },
  suite: {
    maxNights: 21,
    maxGuests: 4,
    rate: 150,
    peakRate: 60,
    guestSurcharge: 25,
    guestSurchargeThreshold: 2,
  },
  villa: {
    maxNights: 28,
    maxGuests: 8,
    rate: 300,
    peakRate: 120,
    minStay: 3,
    fixedFee: 500,
  },
};

function isRecord(value: unknown): value is Record<string, unknown> {

 return typeof value === "object" && value !== null;
}

function isInteger(value: unknown): value is number {
  return Number.isInteger(value);
}

function isSeason(value: unknown): value is Season {
  return value === "low" || value === "high";
}

function parseRequest(raw: unknown): RawBooking | { error: string } {
  if (!isRecord(raw)) {
    return { error: "malformed request" };
  }
  if (!isInteger(raw.loyaltyYears) || (raw.loyaltyYears as number) < 0) {
    return { error: "bad loyalty" };
  }
  const category = raw.category;
  if (category !== "standard" && category !== "suite" && category !== "villa") {
    return { error: "unknown category" };
  }
  return {
    category,
    loyaltyYears: raw.loyaltyYears as number,
    coupon: raw.coupon,
    nights: raw.nights,
    guests: raw.guests,
    season: raw.season,
  };
}

function quote(req: RawBooking): QuoteResult {
  const rules = CATEGORIES[req.category];
  const { nights, guests, loyaltyYears, season, coupon } = req;

  if (!isInteger(nights) || nights < 1 || nights > rules

.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (rules.minStay !== undefined && nights < rules.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }
  if (!isInteger(guests) || guests < 1 || guests >

rules.maxGuests) {
   return { ok: false, error: "bad guests" };
 }
 if (!isSeason(season)) {
   return { ok: false, error: "bad season" };
 }

 const upgrade = coupon === "VIP" || loyaltyYears >= 3;

 let total

= nights * rules.rate;
 if (season === "high") {
   total += nights * rules.peakRate;
 }
 if (upgrade) {
   total -= Math.floor(total / 10);
 }
 if (rules.guestSurcharge !== undefined && guests > (rules.guestSurcharge

Threshold ?? 0)) {
    total += rules.guestSurcharge;
  }
  if (rules.fixedFee !== undefined) {
    total += rules.fixedFee;
  }

  const policy = upgrade ? "flex" : "strict";
  return {
    ok: true,
    total,
    policy,
    line: `${req.category}:${nights}n:${total}:${policy}`,
  };
}

export function quoteBooking(raw: unknown): QuoteResult {
  const parsed = parseRequest(raw);
  if ("error" in parsed) {
    return { ok: false, error: parsed.error };
  }
  return quote(parsed);
}
